<?php require __DIR__ . '/../includes/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('success','Order status updated.');redirect('admin/orders.php');}$orders=$pdo->query('SELECT * FROM orders ORDER BY created_at DESC')->fetchAll();$pageTitle='Manage orders';require __DIR__ . '/../includes/header.php'; ?><div class="admin-shell"><div class="row g-0"><aside class="col-lg-2 admin-side"><div class="eyebrow">Control room</div><h2 class="h4 mt-2">Nexa admin</h2><nav class="mt-4"><a href="index.php">Overview</a><a href="products.php">Products</a><a href="categories.php">Categories</a><a class="active" href="orders.php">Orders</a><a href="users.php">Users</a></nav></aside><section class="col-lg-10 p-4 p-lg-5"><h1 class="h2 mb-4">Orders</h1><div class="panel table-responsive"><table class="table"><thead><tr><th>#</th><th>Customer</th><th>Payment</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td>#<?= $order['id'] ?></td><td><?= e($order['customer_name']) ?><br><small class="text-secondary"><?= e($order['email']) ?></small></td><td><?= e($order['payment_method']) ?></td><td>$<?= number_format($order['total'],2) ?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="id" value="<?= $order['id'] ?>"><select name="status" class="form-select form-select-sm"><option <?= $order['status']==='pending'?'selected':'' ?>>pending</option><option <?= $order['status']==='processing'?'selected':'' ?>>processing</option><option <?= $order['status']==='shipped'?'selected':'' ?>>shipped</option><option <?= $order['status']==='delivered'?'selected':'' ?>>delivered</option><option <?= $order['status']==='cancelled'?'selected':'' ?>>cancelled</option></select><button class="btn btn-sm btn-outline-dark">Save</button></form></td><td></td></tr><?php endforeach; ?></tbody></table></div></section></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>